Exploring indexes and cardinality with JavaScript — Indexes

---

What belongs in the marked result? Trace the values before revealing.

```js
const collection = {
  objects: [],
  index: new Map(),
  add(...objects) {
    objects.forEach((obj) => {
      if (obj.id === object.id)
        throw new Error(`Object with ID ${object.id} already exists`);

      this.objects.push(object);
      this.index.set(object.id, object);
    });
  },
  get(id) {
    return this.index.get(id);
  },
  remove(id) {
    const object = this.index.get(id);
    if (object) {
      this.objects.splice(this.objects.indexOf(object), 1);
      this.index.delete(id);
    }
  },
};

collection.add(
  { id: 400, name: 'Apple' }, { id: 840, name: 'Banana' },
  { id: 243, name: 'Cherry' }, { id: 123, name: 'Apple' },
  { id: 456, name: 'Banana' }
);

